// Contre-calcul QA : lit les taux nationaux sur mon-entreprise URSSAF (source
// indépendante de la page URSSAF WF-S4) et construit des signaux de veille.
// NB: smic.horaire RETIRÉ (2026-06-30) — mon-entreprise renvoie 12,02 € et n'intègre
// pas la revalorisation infra-annuelle (SMIC courant 12,31 € depuis le décret 14/06/2026)
// → comparé à smic.horaire_brut (courant) il créerait un FAUX signal. Le SMIC est couvert
// par WF-S3 (INSEE BDM, source autoritaire). On garde 9 taux nationaux-fixes fiables.
const RULES = [
  { paramKey: 'cotisations.vieillesse_plaf_pat',   rule: 'salarié . cotisations . vieillesse . employeur . plafonnée . taux' },
  { paramKey: 'cotisations.vieillesse_plaf_sal',   rule: 'salarié . cotisations . vieillesse . salarié . plafonnée . taux' },
  { paramKey: 'cotisations.vieillesse_deplaf_pat', rule: 'salarié . cotisations . vieillesse . employeur . déplafonnée . taux' },
  { paramKey: 'cotisations.vieillesse_deplaf_sal', rule: 'salarié . cotisations . vieillesse . salarié . déplafonnée . taux' },
  { paramKey: 'cotisations.chomage_pat',           rule: 'salarié . cotisations . chômage . taux' },
  { paramKey: 'cotisations.csg_deductible',        rule: 'salarié . cotisations . CSG-CRDS . CSG . déductible . taux' },
  { paramKey: 'cotisations.crds',                  rule: 'salarié . cotisations . CSG-CRDS . CRDS . taux' },
  { paramKey: 'cotisations.apprentissage_solde',   rule: "salarié . cotisations . taxe d'apprentissage . solde" },
  { paramKey: 'plafonds.pmss',                     rule: 'plafond sécurité sociale', isEuro: true },
];
function targetYM() { const d = new Date(); return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1 }; }
function condSatisfied(si, t) {
  const m = String(si).match(/(\d{1,2})\/(\d{4})/);
  if (!m) return false;
  const bm = Number(m[1]), by = Number(m[2]);
  return t.y > by || (t.y === by && t.m >= bm);
}
function resolveScalar(rawNode, t) {
  if (rawNode == null) return null;
  if (typeof rawNode === 'string' || typeof rawNode === 'number') return rawNode;
  if (rawNode.valeur != null) return rawNode.valeur;
  if (Array.isArray(rawNode.produit)) return rawNode.produit[rawNode.produit.length - 1];
  if (Array.isArray(rawNode.variations)) {
    for (const v of rawNode.variations) {
      if (v && 'sinon' in v) return v.sinon;
      if (v && v.si != null && condSatisfied(v.si, t)) return v.alors;
    }
    const last = rawNode.variations.find((v) => v && 'sinon' in v);
    return last ? last.sinon : null;
  }
  return null;
}
function normalize(scalar, isEuro) {
  if (scalar == null) return null;
  const s = String(scalar).trim();
  if (isEuro) { const n = Number(s.replace(/[^\d.,-]/g, '').replace(',', '.')); return Number.isFinite(n) ? n : null; }
  if (s.includes('%')) { const n = Number(s.replace('%', '').replace(',', '.').trim()); return Number.isFinite(n) ? n / 100 : null; }
  const n = Number(s.replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}
const t = targetYM();
const base = 'https://mon-entreprise.urssaf.fr/api/v1/rules/';
const signals = [];
for (const r of RULES) {
  try {
    const resp = await this.helpers.httpRequest({ method: 'GET', url: base + encodeURIComponent(r.rule), json: true, headers: { 'User-Agent': 'acme' } });
    const scalar = resolveScalar(resp && resp.rawNode ? resp.rawNode : resp, t);
    const val = normalize(scalar, r.isEuro);
    if (val == null || val <= 0) continue;
    if (!r.isEuro && val > 0.5) continue;
    signals.push({
      sourceKey: 'openfisca_mon_entreprise',
      paramKey: r.paramKey,
      valeurProposee: r.isEuro ? val.toFixed(2) : val.toFixed(5),
      dateEffet: t.y + '-01-01',
      urlSource: base + encodeURIComponent(r.rule),
      extrait: r.paramKey + ' = ' + scalar + ' (mon-entreprise URSSAF, contre-calcul QA)',
      confiance: 0.95,
    });
  } catch (e) { /* règle en échec : on saute, pas de signal */ }
  await new Promise((res) => setTimeout(res, 1500));
}
return [{ json: { ran: true, emitted: signals.length, signals } }];
